export type LifecycleKind = "arrival" | "leave" | "milestone" | "reengagement";
export interface LifecyclePolicy { sourceRevision: string; maxStateAgeMinutes: number; provenance: { source: string; sourceRevision: string; observedAt: string }; cooldownHours: number; quietInterval: { utcOffsetMinutes: number; startMinute: number; endMinute: number }; templates: { arrival: string; leave: string; milestone: string; reengagement: string; digest: string } }
export interface LifecycleState { sourceRevision: string; observedAt: string; lastContactAt: string | null; priorReceipts: Array<{ dedupeKey: string; kind: LifecycleKind }> }
export interface LifecycleEvent { eventId: string; sourceRevision: string; occurredAt: string; completedParticipation: boolean | null; tenureStartedAt: string | null; explicitOptIn: boolean | null }
export interface LifecycleProposal { type: "DiscordMemberLifecycleProposal"; version: 1; proposalId: string; communityId: string; memberId: string; kind: LifecycleKind; eventId: string; sourceRevision: string; policyDigest: string; eventDigest: string; stateDigest: string; dedupeKey: string; allowedMentions: "none"; delivery: "forbidden"; executable: false }
export function planMemberLifecycle(input: { communityId: string; memberId: string; kind: LifecycleKind; now: Date | string; policy: LifecyclePolicy; state: LifecycleState; event: LifecycleEvent }): Readonly<LifecycleProposal>;
export function validateLifecyclePlan(plan: LifecycleProposal): Readonly<LifecycleProposal>;
export function projectLifecycleReceipt(plan: LifecycleProposal, options: { key: string; purpose: string; recordedAt: string }): Readonly<{ type: "DiscordMemberLifecycleReceipt"; version: 1; purpose: string; kind: LifecycleKind; recordedAt: string; receiptHmac: string; privacy: { omitted: string[] } }>;
